import re
def parse(path):
    out=[]; cur=None
    for line in open(path,errors='replace'):
        m=re.match(r'\* FPS infos\. Frame=([\d.]+)ms, FPS:([\d.]+)',line)
        if m:
            cur={'frame':float(m.group(1)),'t':{}, 'drones':0,'veh':0}; out.append(cur); continue
        if cur is None: continue
        m=re.match(r'\s*([\d.]+) ms - (\S+(?: [^\n]*?)?)\s*(\(subtotal.*)?$',line.rstrip())
        if m:
            name=m.group(2).strip()
            cur['t'][name]=float(m.group(1)); continue
        m=re.search(r'nbDrones=(\d+).*nbVehicles=(\d+)',line)
        if m: cur['drones']=int(m.group(1)); cur['veh']=int(m.group(2))
    return out
